    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        if (empty($this->orders)) {
            $this->command->error('No order data provided in the array.');
            return;
        }

        $this->command->info('Starting Order migration from array...');
        $this->command->getOutput()->progressStart(count($this->orders));

        foreach ($this->orders as $orderr) {
            try {
                \DB::beginTransaction();

                $this->command->info('Processing order number : '.$orderr['order_number'].', Placed By '. $orderr['placed_by']);

                // Create new User
                $order = new Order();
                $order->id = $orderr['id'];
                $order->order_number = $orderr['order_number'];
                $order->user_id = $orderr['buyer_id'];
                $order->category_id = null;
                $order->price_subtotal = $orderr['price_subtotal'];
                $order->price_gst = $orderr['price_gst'];
                $order->price_shipping = $orderr['price_shipping'];
                $order->discounted_price = $orderr['discounted_price'];
                $order->price_total = $orderr['price_total'];
                $order->payment_method = $orderr['payment_method'];
                $order->payment_status = $orderr['payment_status'];
                $order->status = $orderr['status'];
                $order->order_status = $orderr['order_status'];
                $order->delivered_date = $orderr['delivered_date'];
                $order->placed_by = $orderr['placed_by'];
                $order->created_at = $orderr['created_at'];
                $order->updated_at = $orderr['updated_at'];
                $order->save();

                \DB::commit();
                $this->command->getOutput()->progressAdvance();
            } catch (\Exception $e) {
                \DB::rollBack();
                $this->command->error("Failed to migrate order" . $e->getMessage());  
            }
        }

        $this->command->getOutput()->progressFinish();
        $this->command->info('Order migration from array completed.');
    }
